// Lektion "Pattern Matching für switch und Record Patterns" (Java 21+, final).
// Ausführen: java PatternSwitchDemo.java
import java.math.BigDecimal;

public class PatternSwitchDemo {

    record Money(BigDecimal amount, String currency) {}
    record Point(int x, int y) {}

    static String describe(Object input) {
        return switch (input) {
            case null -> "kein Wert";
            case Integer i when i < 0 -> "negative Zahl " + i;
            case Integer i -> "Zahl " + i;
            case String s when s.isBlank() -> "leerer Text";
            case String s -> "Text mit " + s.length() + " Zeichen";
            case Money(var amount, var currency) when amount.signum() == 0 -> "kostenlos in " + currency;
            case Money(var amount, var currency) -> amount + " " + currency;
            case Point(int x, int y) when x == y -> "Diagonalpunkt " + x;
            case Point(int x, int y) -> "Punkt (" + x + "|" + y + ")";
            default -> "unbekannt: " + input.getClass().getSimpleName();
        };
    }

    public static void main(String[] args) {
        Object[] samples = {
            null, -4, 7, "  ", "Java",
            new Money(BigDecimal.ZERO, "EUR"), new Money(new BigDecimal("19.90"), "EUR"),
            new Point(3, 3), new Point(1, 2), 3.5
        };
        for (Object sample : samples) System.out.println(describe(sample));
    }
}

// Lektion "Sealed Types und Records als Domänenmodell" (Java 21+, final).
// Ausführen: java SealedResultDemo.java
public class SealedResultDemo {

    sealed interface Result<T> permits Ok, Failure {}
    record Ok<T>(T value) implements Result<T> {}
    record Failure<T>(String reason, int code) implements Result<T> {}

    sealed interface PaymentMethod permits Card, Invoice, Voucher {}
    record Card(String lastFour) implements PaymentMethod {}
    record Invoice(int dueDays) implements PaymentMethod {}
    record Voucher(String code, int percent) implements PaymentMethod {}

    // Kein default: Der Compiler prüft Vollständigkeit. Kommt ein vierter Typ hinzu,
    // schlägt die Kompilierung hier fehl - nicht erst ein Test oder die Produktion.
    static String label(PaymentMethod method) {
        return switch (method) {
            case Card(var lastFour) -> "Karte ****" + lastFour;
            case Invoice(var dueDays) -> "Rechnung, zahlbar in " + dueDays + " Tagen";
            case Voucher(var code, var percent) -> "Gutschein " + code + " (-" + percent + " %)";
        };
    }

    static Result<Integer> parseAge(String text) {
        try {
            int age = Integer.parseInt(text.trim());
            return age < 0 ? new Failure<>("Alter darf nicht negativ sein", 422) : new Ok<>(age);
        } catch (NumberFormatException e) {
            return new Failure<>("Keine Zahl: '" + text + "'", 400);
        }
    }

    public static void main(String[] args) {
        System.out.println(label(new Card("4242")));
        System.out.println(label(new Invoice(14)));
        System.out.println(label(new Voucher("SOMMER", 10)));
        for (String input : new String[] {"42", "-1", "abc"}) {
            String message = switch (parseAge(input)) {
                case Ok<Integer>(var value) -> "OK: " + value;
                case Failure<Integer>(var reason, var code) -> "Fehler " + code + ": " + reason;
            };
            System.out.println(message);
        }
    }
}

// Lektion "Sequenced Collections und neue Alltags-APIs" (Java 21+, final).
// Ausführen: java SequencedDemo.java
import java.util.*;

public class SequencedDemo {
    public static void main(String[] args) {
        List<String> queue = new ArrayList<>(List.of("b", "c", "d"));
        queue.addFirst("a");
        queue.addLast("e");
        System.out.println(queue + " first=" + queue.getFirst() + " last=" + queue.getLast());

        // reversed() ist eine SICHT, keine Kopie: Änderungen wirken auf beide Seiten.
        List<String> view = queue.reversed();
        view.addFirst("Z");              // landet hinten in der Originalliste
        System.out.println(view + " | Original: " + queue);

        LinkedHashMap<String, Integer> scores = new LinkedHashMap<>();
        scores.put("anna", 3);
        scores.put("ben", 5);
        scores.putFirst("clara", 9);     // Java 21: Position ist steuerbar
        System.out.println(scores + " firstEntry=" + scores.firstEntry() + " lastEntry=" + scores.lastEntry());
        System.out.println(scores.reversed());

        LinkedHashSet<Integer> ids = new LinkedHashSet<>(List.of(1, 2, 3));
        ids.addFirst(3);                 // bestehendes Element wandert nach vorn
        System.out.println(ids);

        try {
            new ArrayList<String>().getFirst();
        } catch (NoSuchElementException e) {
            System.out.println("Leere Liste: getFirst() wirft NoSuchElementException");
        }
        try {
            List.of(1, 2).reversed().addFirst(9);
        } catch (UnsupportedOperationException e) {
            System.out.println("Unveränderliche Liste: addFirst() über reversed() wirft UnsupportedOperationException");
        }
    }
}

// Lektion "Virtual Threads: wann sie helfen und wann nicht" (Java 21+, final).
// Ausführen: java VirtualThreadsDemo.java
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class VirtualThreadsDemo {

    static String slowCall(int id) throws InterruptedException {
        Thread.sleep(Duration.ofMillis(200));   // simuliert blockierendes I/O
        return "antwort-" + id;
    }

    public static void main(String[] args) throws Exception {
        long start = System.nanoTime();
        List<Future<String>> futures = new ArrayList<>();
        // Pro Aufgabe ein neuer virtueller Thread: NICHT poolen, die sind billig.
        try (ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < 5_000; i++) {
                final int id = i;
                futures.add(executor.submit(() -> slowCall(id)));
            }
        } // close() wartet, bis alle Aufgaben beendet sind
        long ms = Duration.ofNanos(System.nanoTime() - start).toMillis();
        System.out.println("5000 Aufgaben à 200 ms in " + ms + " ms (sequenziell wären das 1000 s)");
        System.out.println("letztes Ergebnis: " + futures.getLast().get());

        // Begrenzung einer knappen Ressource (z. B. Datenbankverbindungen) mit Semaphore statt Poolgröße.
        Semaphore permits = new Semaphore(10);
        AtomicInteger maxParallel = new AtomicInteger();
        AtomicInteger running = new AtomicInteger();
        try (ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < 200; i++) {
                executor.submit(() -> {
                    permits.acquire();
                    try {
                        maxParallel.accumulateAndGet(running.incrementAndGet(), Math::max);
                        Thread.sleep(20);
                        running.decrementAndGet();
                    } finally {
                        permits.release();
                    }
                    return null;
                });
            }
        }
        System.out.println("max. gleichzeitig: " + maxParallel.get() + " (Limit 10)");

        Thread t = Thread.ofVirtual().name("demo-vthread").start(() ->
            System.out.println("virtuell? " + Thread.currentThread().isVirtual()));
        t.join();
    }
}

// Lektion "Structured Concurrency und Scoped Values".
// ScopedValue ist seit Java 25 final. StructuredTaskScope ist in Java 26 noch Preview (JEP 525).
// Ausführen (JDK 26): java --enable-preview --source 26 StructuredScopesDemo.java
import java.time.Duration;
import java.util.concurrent.StructuredTaskScope;
import java.util.concurrent.StructuredTaskScope.Joiner;
import java.util.concurrent.StructuredTaskScope.Subtask;

public class StructuredScopesDemo {

    static final ScopedValue<String> REQUEST_ID = ScopedValue.newInstance();

    static String findUser() throws InterruptedException {
        Thread.sleep(Duration.ofMillis(100));
        return "anna (Request " + REQUEST_ID.get() + ")";   // Wert wird in Kind-Threads vererbt
    }

    static int fetchOrderCount() throws InterruptedException {
        Thread.sleep(Duration.ofMillis(150));
        return 3;
    }

    static int failingCall() throws InterruptedException {
        Thread.sleep(Duration.ofMillis(50));
        throw new IllegalStateException("Bestellsystem nicht erreichbar");
    }

    static String slowCall() throws InterruptedException {
        try {
            Thread.sleep(Duration.ofSeconds(10));       // würde ohne Scope weiterlaufen
            return "zu spät";
        } catch (InterruptedException e) {
            System.out.println("  slowCall wurde abgebrochen (interrupt)");
            throw e;
        }
    }

    public static void main(String[] args) throws Exception {
        // 1) Beide Teilaufgaben müssen gelingen; scope.join() wirft sonst eine Ausnahme.
        ScopedValue.where(REQUEST_ID, "r-42").run(() -> {
            try (var scope = StructuredTaskScope.open()) {
                Subtask<String> user = scope.fork(StructuredScopesDemo::findUser);
                Subtask<Integer> orders = scope.fork(StructuredScopesDemo::fetchOrderCount);
                scope.join();
                System.out.println("1) " + user.get() + ", Bestellungen: " + orders.get());
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });

        // 2) Fehlerfall: Eine Teilaufgabe scheitert, die langsame wird automatisch abgebrochen.
        try (var scope = StructuredTaskScope.open()) {
            scope.fork(StructuredScopesDemo::slowCall);
            scope.fork(StructuredScopesDemo::failingCall);
            scope.join();
        } catch (StructuredTaskScope.FailedException e) {
            System.out.println("2) Gescheitert: " + e.getCause().getMessage());
        }

        // 3) Wettlauf: Das erste erfolgreiche Ergebnis zählt, der Rest wird abgebrochen (Java 26: anySuccessfulOrThrow).
        try (var scope = StructuredTaskScope.open(Joiner.<String>anySuccessfulOrThrow())) {
            scope.fork(() -> { Thread.sleep(Duration.ofMillis(300)); return "Mirror B"; });
            scope.fork(() -> { Thread.sleep(Duration.ofMillis(50)); return "Mirror A"; });
            System.out.println("3) Schnellste Antwort: " + scope.join());
        }
    }
}

// Lektion "Stream Gatherers und unbenannte Variablen".
// Gatherer: final seit Java 24 (JEP 485). Unbenannte Variablen "_": final seit Java 22 (JEP 456).
// Ausführen: java GatherersDemo.java   (JDK 24 oder neuer)
import java.util.List;
import java.util.Map;
import java.util.stream.Gatherer;
import java.util.stream.Gatherers;
import java.util.stream.Stream;

public class GatherersDemo {

    // Eigener Gatherer: entfernt direkt aufeinanderfolgende Duplikate (zustandsbehaftet).
    static <T> Gatherer<T, ?, T> dropConsecutiveDuplicates() {
        return Gatherer.ofSequential(
            () -> new Object() { T last; boolean hasLast; },
            (state, element, downstream) -> {
                if (state.hasLast && state.last.equals(element)) return true;   // weiter, nichts ausgeben
                state.last = element;
                state.hasLast = true;
                return downstream.push(element);                                 // false = Downstream will nichts mehr
            });
    }

    public static void main(String[] args) {
        System.out.println(Stream.of(1, 2, 3, 4, 5, 6, 7).gather(Gatherers.windowFixed(3)).toList());
        System.out.println(Stream.of(1, 2, 3, 4, 5).gather(Gatherers.windowSliding(2)).toList());
        System.out.println(Stream.of(1, 2, 3, 4).gather(Gatherers.scan(() -> 0, Integer::sum)).toList());
        System.out.println(Stream.of("a", "b", "b", "b", "c", "a", "a").gather(dropConsecutiveDuplicates()).toList());

        // Parallel begrenzte Abbildung mit virtuellen Threads (z. B. für blockierende Aufrufe).
        List<String> pages = Stream.of(1, 2, 3, 4, 5, 6)
            .gather(Gatherers.mapConcurrent(3, id -> "Seite-" + id))
            .toList();
        System.out.println(pages);

        // Unbenannte Variablen: "_" macht sichtbar, dass ein Wert bewusst nicht gebraucht wird.
        Map<String, Integer> counts = Map.of("a", 1, "b", 2, "c", 3);
        int entries = 0;
        for (var _ : counts.entrySet()) entries++;
        System.out.println("Einträge: " + entries);

        try {
            Integer.parseInt("kaputt");
        } catch (NumberFormatException _) {
            System.out.println("Ungültige Zahl, Ausnahme bewusst nicht weiterverwendet");
        }
    }
}

