import { computed, nextTick, reactive, ref, shallowRef, toRefs, toValue, triggerRef, watch, watchEffect, type MaybeRefOrGetter } from 'vue';

// Lektion "Reaktivitätsfallen": Jede Falle steht als Paar "falsch" und "richtig", damit Test und Lektion beides zeigen.

// 1) Destrukturieren kopiert den Wert: Die Kopie bleibt stehen, während der Zustand sich ändert.
export function destructuredCopyGoesStale() {
  const state = reactive({ count: 0 });
  const { count } = state;                // Kopie der Zahl 0, keine Verbindung mehr zu state
  state.count = 5;
  return { state: state.count, copy: count };
}
export function toRefsStaysLive() {
  const state = reactive({ count: 0 });
  const { count } = toRefs(state);        // count ist eine ref, die auf state.count zeigt
  state.count = 5;
  const viaRef = count.value;
  count.value = 7;                         // Schreiben geht auch in die andere Richtung
  return { viaRef, state: state.count };
}

// 2) Ein reactive-Objekt kann man nicht als Ganzes ersetzen: Wer die alte Referenz hält, sieht keine Änderungen.
export function replacingReactiveBreaksLink() {
  let state = reactive({ items: ['a'] });
  const held = state;                      // z. B. an eine Komponente oder ein Composable weitergegeben
  state = reactive({ items: ['a', 'b'] }); // neues Objekt: held zeigt weiter auf das alte
  return { held: held.items.length, current: state.items.length };
}
export function refCanBeReplaced() {
  const state = ref({ items: ['a'] });
  const held = state;                      // dieselbe ref
  state.value = { items: ['a', 'b'] };     // Inhalt austauschen, die Referenz bleibt
  return { held: held.value.items.length, current: state.value.items.length };
}

// 3) shallowRef verfolgt nur den Austausch von .value, nicht Änderungen im Inneren.
export async function shallowRefTracksOnlyValue() {
  const box = shallowRef({ n: 0 });
  let runs = 0;
  watch(box, () => { runs++; });
  box.value.n++;                           // tief verändert: keine Benachrichtigung
  await nextTick();
  const afterMutation = runs;
  triggerRef(box);                         // manuell auslösen
  await nextTick();
  const afterTrigger = runs;
  box.value = { n: 5 };                    // Austausch: Benachrichtigung
  await nextTick();
  return { afterMutation, afterTrigger, afterReplace: runs };
}

// 4) watchEffect sammelt Abhängigkeiten nur SYNCHRON, also vor dem ersten await.
export async function watchEffectLosesDependenciesAfterAwait() {
  const a = ref(1);
  const b = ref(1);
  const seen: string[] = [];
  watchEffect(async () => {
    const first = a.value;                 // wird verfolgt
    await Promise.resolve();
    seen.push(`${first}/${b.value}`);      // b.value wird NICHT verfolgt
  });
  await nextTick(); await Promise.resolve();
  b.value = 2;                             // löst keinen neuen Lauf aus
  await nextTick(); await Promise.resolve();
  a.value = 2;                             // löst aus
  await nextTick(); await Promise.resolve(); await Promise.resolve();
  return seen;
}
export async function watchWithExplicitSources() {
  const a = ref(1);
  const b = ref(1);
  const seen: string[] = [];
  watch([a, b], async ([nextA, nextB]) => {   // Quellen stehen ausdrücklich da, auch nach await ändert das nichts
    await Promise.resolve();
    seen.push(`${nextA}/${nextB}`);
  });
  b.value = 2; await nextTick(); await Promise.resolve();
  a.value = 2; await nextTick(); await Promise.resolve();
  return seen;
}

// 5) Zeitpunkt von Watchern (flush: 'pre' | 'post') zeigt FlushDemo.vue am echten DOM.

// 6) Props an Composables: Wer den Wert übergibt, übergibt eine Momentaufnahme. MaybeRefOrGetter + toValue löst das.
export function useUppercase(source: MaybeRefOrGetter<string>) {
  return computed(() => toValue(source).toUpperCase());
}
export function snapshotVersusGetter() {
  const name = ref('ada');
  const snapshot = useUppercase(name.value);     // String: wird nie wieder aktualisiert
  const live = useUppercase(() => name.value);   // Getter: bleibt aktuell
  name.value = 'grace';
  return { snapshot: snapshot.value, live: live.value };
}

// 7) Refs in reactive-Arrays und -Maps werden NICHT automatisch entpackt (in Objekten schon).
export function refsInsideReactiveCollections() {
  const object = reactive({ n: ref(1) });
  const list = reactive([ref(1)]);
  return { objectUnwrapped: typeof object.n === 'number', listUnwrapped: typeof list[0] === 'number', listItemValue: list[0]!.value };
}

import * as z from 'zod';

// Lektion "Dynamische Formulare": Eine Liste von Eingabezeilen mit Zod prüfen.
export const MAX_MEMBERS = 5;

// "key" gehört nur der Oberfläche (stabile Identität einer Zeile für v-for) und verlässt das Formular nicht.
const memberSchema = z.object({
  key: z.string(),
  email: z.string().trim().min(1, { error: 'E-Mail fehlt' })
    .pipe(z.email({ error: 'Gültige E-Mail-Adresse eingeben' }))
    .transform((value) => value.toLowerCase()),
});

export const inviteSchema = z.object({
  team: z.string().trim().min(1, { error: 'Teamname fehlt' }).max(40, { error: 'Teamname darf höchstens 40 Zeichen haben' }),
  members: z.array(memberSchema)
    .min(1, { error: 'Mindestens eine Person einladen' })
    .max(MAX_MEMBERS, { error: `Höchstens ${MAX_MEMBERS} Personen einladen` }),
}).superRefine((value, ctx) => {
  // Doppelte Adressen: die ZWEITE und jede weitere Zeile bekommt den Fehler, nicht die erste.
  const seen = new Set<string>();
  value.members.forEach((member, index) => {
    if (seen.has(member.email)) ctx.addIssue({ code: 'custom', path: ['members', index, 'email'], message: 'Diese Adresse steht schon in der Liste' });
    seen.add(member.email);
  });
}).transform((value) => ({ team: value.team, emails: value.members.map((member) => member.email) }));   // API-Form ohne UI-Schlüssel

export type InviteInput = z.input<typeof inviteSchema>;
export type InviteData = z.output<typeof inviteSchema>;
/** Schlüssel: "team", "members" (Listenfehler) oder "members.<Index>.email" (Zeilenfehler). */
export type InviteErrors = Record<string, string>;

export function validateInvite(raw: unknown): { ok: true; data: InviteData } | { ok: false; errors: InviteErrors } {
  const result = inviteSchema.safeParse(raw);
  if (result.success) return { ok: true, data: result.data };
  const errors: InviteErrors = {};
  for (const issue of result.error.issues) {
    const key = issue.path.join('.');
    errors[key] ??= issue.message;                       // je Feld die erste Meldung
  }
  return { ok: false, errors };
}

import { useInfiniteQuery, useQuery, type QueryClient } from '@tanstack/vue-query';
import { computed, type MaybeRefOrGetter, toValue } from 'vue';
import { ApiError } from '../data/tasksApi';
import type { Activity, ActivityApi } from './activityApi';

export const activityKeys = {
  all: ['activity'] as const,
  list: () => ['activity', 'list'] as const,
  detail: (id: number) => ['activity', 'detail', id] as const,
};

/**
 * Wiederholungsstrategie: nur bei vorübergehenden Fehlern (Netzwerk, 5xx, 408, 429), höchstens zweimal.
 * Ein 404 oder 422 wird durch Wiederholen nicht besser; es würde nur den Server belasten.
 */
export function shouldRetry(failureCount: number, error: unknown): boolean {
  if (failureCount >= 2) return false;
  if (error instanceof ApiError) return error.status >= 500 || error.status === 408 || error.status === 429;
  return error instanceof TypeError;                         // fetch meldet Netzwerkfehler als TypeError
}
/** Exponentielles Warten mit Obergrenze: 1 s, 2 s, 4 s … höchstens 8 s. */
export const backoff = (attempt: number) => Math.min(1000 * 2 ** attempt, 8000);

export function useActivityFeed(api: ActivityApi, options: { retryDelay?: number | ((attempt: number) => number) } = {}) {
  const query = useInfiniteQuery({
    queryKey: activityKeys.list(),
    queryFn: ({ pageParam, signal }) => api.list(pageParam, signal),
    initialPageParam: null as string | null,                // erste Seite: kein Cursor
    getNextPageParam: (lastPage) => lastPage.nextCursor ?? undefined,    // undefined = keine weitere Seite
    retry: shouldRetry,
    retryDelay: options.retryDelay ?? backoff,
    staleTime: 30_000,
  });
  // Neue Einträge können zwischen zwei Seiten die Cursor verschieben: dieselbe id darf nicht doppelt erscheinen.
  const items = computed<Activity[]>(() => {
    const seen = new Set<number>();
    return (query.data.value?.pages ?? []).flatMap((page) => page.items).filter((item) => !seen.has(item.id) && seen.add(item.id));
  });
  return { ...query, items };
}

export function useActivityDetail(api: ActivityApi, id: MaybeRefOrGetter<number | null>) {
  return useQuery({
    queryKey: computed(() => activityKeys.detail(toValue(id) ?? -1)),
    queryFn: ({ signal }) => api.detail(toValue(id) as number, signal),
    enabled: computed(() => toValue(id) !== null),
    retry: shouldRetry,                                      // Standard wäre 3 Wiederholungen: ein 404 bliebe sekundenlang "Lade …"
    retryDelay: backoff,
    staleTime: 60_000,                                       // so lange gilt ein Vorab-Laden als frisch
  });
}

/** Beim Überfahren oder Fokussieren eines Eintrags vorladen: Der spätere Klick findet die Daten schon im Cache. */
export function prefetchActivity(client: QueryClient, api: ActivityApi, id: number) {
  return client.prefetchQuery({
    queryKey: activityKeys.detail(id),
    queryFn: ({ signal }) => api.detail(id, signal),
    staleTime: 60_000,
  });
}

